 const API='api.php'; let pin=window.EARTHSCOPE_SELECTED_PLACE||null, current='overview', fieldPoints=[], fields=readStore('earthscope-fields-v3',[]), collection=readStore('earthscope-collections-v3',[]), cropRows=[], lastTripPlan=null;
