 function pinCoords(){pin=window.EARTHSCOPE_SELECTED_PLACE||pin;return pin&&Number.isFinite(Number(pin.lat))&&Number.isFinite(Number(pin.lon))?{name:pin.name||'Selected point',lat:Number(pin.lat),lon:Number(pin.lon)}:null}
 function open(){modal.hidden=false;document.body.style.overflow='hidden';syncPin();$('es-close').focus()};function close(){modal.hidden=true;document.body.style.overflow='';launcher.focus()};function jump(view){current=view;modal.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===view)));modal.querySelectorAll('[data-view-panel]').forEach(p=>p.hidden=p.dataset.viewPanel!==view);const titles={overview:['All of EarthScope, connected','Explore and act from one workspace.'],control:['Earth Control Center','Weather, soil, hazards and nearby context for your selected pin.'],trip:['AI trip & route planner','Road route, duration and transparent budget estimates.'],field:['Farm fields & economics','Draw a field, measure area, compare crop economics and print A4 reports.'],species:['Global crop & species atlas','Search a living global taxonomy and inspect potential candidates.'],food:['Food Studio','Turn ingredients, location and budget into meal ideas.'],ninjas:['API Ninjas Data Lab','Weather, air quality, nutrition, recipes, vehicle specs and country data.'],time:['Earth Time Machine','Open real satellite imagery archives and synchronized date comparison.'],collections:['My Earth collections','Keep pins, field boundaries, trip ideas and reports in this browser.'],quests:['Earth quests & learning','Interactive geography, climate, biodiversity and farm learning.']};$('es-title').textContent=titles[view][0];$('es-subtitle').textContent=titles[view][1];if(view==='field'){calcCompare();renderFields()}if(view==='collections')renderCollections();if(view==='control')renderPinSummary();if(view==='ninjas'){syncNinjasPin();checkNinjasStatus()}if(view==='food')$('es-food-pin').textContent=pinCoords()?`Using ${pinCoords().name} (${round(pin.lat,4)}, ${round(pin.lon,4)}). Open Food Studio to use ingredients, dietary preferences and budget.`:'Choose a map pin for location-aware seasonal ideas.'}
