 function syncPin(){pin=window.EARTHSCOPE_SELECTED_PLACE||pin;const p=pinCoords();const text=p?`${p.name}\nLatitude: ${p.lat.toFixed(5)}\nLongitude: ${p.lon.toFixed(5)}\nUse this point for weather, soil context, nearby discovery and preliminary crop research.`:'No map pin selected yet. Open Globe Explorer and click anywhere on the map.';['es-pin-card'].forEach(id=>{if($(id))$(id).textContent=text});if(p){if($('es-origin')&&!$('es-origin').value)$('es-origin').value=`${p.lat}, ${p.lon}`;if($('es-time-place')&&!$('es-time-place').value)$('es-time-place').value=p.name;$('es-control-sub').textContent=`Selected: ${p.name} (${p.lat.toFixed(4)}, ${p.lon.toFixed(4)}). Load a source-backed snapshot; feeds can be incomplete.`}else $('es-control-sub').textContent='No map pin selected. Select one in Globe Explorer, then load location-aware sources.'}
 function goMain(panel){close();const b=document.querySelector(`.nav-item[data-panel="${panel}"]`);if(b)b.click();else if(window.EARTHSCOPE_BRIDGE?.showPanel)window.EARTHSCOPE_BRIDGE.showPanel(panel)}
 launcher.addEventListener('click',open);$('es-close').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(!modal.hidden&&e.key==='Escape')close()});modal.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>jump(b.dataset.view)));modal.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>jump(b.dataset.jump)));modal.querySelectorAll('[data-nearby]').forEach(b=>b.addEventListener('click',()=>nearby(b.dataset.nearby,'es-collection-nearby')));window.addEventListener('earthscope:placechange',e=>{pin=e.detail;syncPin();if(current==='food')$('es-food-pin').textContent=`Using ${pin.name} (${round(pin.lat,4)}, ${round(pin.lon,4)}). Open Food Studio to use ingredients, dietary preferences and budget.`});
 $('es-copy-pin').addEventListener('click',async()=>{const p=pinCoords();if(!p){alert('Select a map pin first.');return}const txt=`${p.lat}, ${p.lon}`;try{await navigator.clipboard.writeText(txt)}catch(_){prompt('Copy coordinates',txt)}});$('es-share-pin').addEventListener('click',async()=>{const p=pinCoords();if(!p){alert('Select a map pin first.');return}const u=new URL(location.href);u.searchParams.set('lat',p.lat.toFixed(6));u.searchParams.set('lon',p.lon.toFixed(6));u.searchParams.set('place',p.name);const link=u.toString();try{await navigator.clipboard.writeText(link);alert('Shareable EarthScope link copied. It opens the map at this location.')}catch(_){prompt('Copy shareable map link',link)}});$('es-map-pin').addEventListener('click',()=>goMain('explore'));$('es-save-pin').addEventListener('click',()=>savePinToCollection());$('es-collect-pin').addEventListener('click',()=>savePinToCollection());$('es-ai-pin').addEventListener('click',()=>{jump('control');$('es-ai-question').value='Summarize this selected location using available sources. Include weather, soil uncertainty, nearby hazards, land/nature context and what important data is missing.';$('es-ai-form').requestSubmit()});$('es-ai-open-main').addEventListener('click',()=>{close();$('open-assistant')?.click()});
 async function askAI(question, answerId, extra={}){const p=pinCoords(),out=$(answerId);out.textContent='Asking the configured Earth AI…';try{const ctx={selected_place:p?.name||'',coordinates:p?{lat:p.lat,lon:p.lon}:null,source_facts:extra.facts||[]};const r=await api('assistant',{}, {question,context:ctx,language:$('es-ai-language')?.value||'en-US'});out.textContent=r.answer||'No answer returned.'}catch(e){out.textContent=`AI request unavailable: ${e.message}\n\nYou can still use public-source map, weather, soil and taxonomy searches without AI. Check server-side OpenRouter configuration and model availability.`}}
