 function statCard(title,value,detail,source){return `<article class="es-dash-card"><small>${esc(title)}</small><strong>${esc(value)}</strong><span>${esc(detail)}</span><em>${esc(source)}</em></article>`}function countItems(r){const d=r.data||r;return (d.features||d.results||d.items||d.events||[]).length||'Feed'}
