 ['es-origin','es-destination','es-efficiency','es-fuel','es-days','es-daily','es-trip-style','es-trip-requirements','es-trip-budget'].forEach(id=>$(id).addEventListener('input',()=>{lastTripPlan=null;$('es-save-trip-plan').disabled=true}));$('es-route-pin').addEventListener('click',()=>{const p=pinCoords();if(!p){alert('Select a map pin first.');return}$('es-origin').value=`${p.lat}, ${p.lon}`;lastTripPlan=null;$('es-save-trip-plan').disabled=true});$('es-save-trip-plan').addEventListener('click',()=>{if(!lastTripPlan){alert('Calculate a route first.');return}const item={...lastTripPlan,id:Date.now().toString(36),notes:`${fmt(lastTripPlan.distanceKm)} km · ${fmt(lastTripPlan.durationHours)} h estimated · fuel ${fmt(lastTripPlan.fuelCost)} · subtotal ${fmt(lastTripPlan.estimatedSubtotal)}`};collection.unshift(item);if(!writeStore('earthscope-collections-v3',collection)){alert('Browser storage is full; export or remove old collection records.');return}renderCollections();alert('Trip plan saved in this browser. Export Collections to back it up or move it to another device.')});$('es-trip-ai').addEventListener('click',()=>askAI(`Plan a ${$('es-days').value}-day ${$('es-trip-style').value} trip from ${$('es-origin').value} to ${$('es-destination').value}. Budget cap ${$('es-trip-budget').value||'not given'}. Additional natural-language preferences: ${$('es-trip-requirements').value||'none supplied'}. Give a day-by-day itinerary, suggested stop types, route considerations, climate expectations only when supported, estimated-cost categories and source links to verify. Clearly label unverified prices/opening information and do not claim a booking is available.`,'es-trip-ai-output'));
 async function geocode(q){const r=await api('geocode',{q});const d=r.data||r,rows=Array.isArray(d)?d:(d.features||d.results||d.items||[]);if(!rows.length)throw Error('No geocoding result for '+q);const x=rows[0],c=x.geometry?.coordinates||x.coordinates,lat=Number(x.lat??x.latitude??c?.[1]),lon=Number(x.lon??x.longitude??c?.[0]);if(!Number.isFinite(lat)||!Number.isFinite(lon))throw Error('Geocoding did not return coordinates');return{lat,lon,name:x.display_name||x.name||q}}
