 function polygonAreaHa(points){if(points.length<3)return 0;const R=6371008.8;let s=0;for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];s+=(Number(b.lon)-Number(a.lon))*Math.PI/180*(2+Math.sin(Number(a.lat)*Math.PI/180)+Math.sin(Number(b.lat)*Math.PI/180))}return Math.abs(s*R*R/2)/10000}function perimeterKm(points){if(points.length<2)return 0;let p=0;for(let i=0;i<points.length;i++)p+=haversine(points[i].lat,points[i].lon,points[(i+1)%points.length].lat,points[(i+1)%points.length].lon);return p}
