 $('es-save-field').addEventListener('click',()=>{window.EARTHSCOPE_BRIDGE?.stopFieldDrawing();if(fieldPoints.length<3){alert('Draw at least 3 vertices.');return}const p=pinCoords(),entry={id:Date.now().toString(36),type:'field',name:$('es-field-name').value.trim()||'Unnamed field',notes:$('es-field-notes').value.trim(),coordinates:fieldPoints.map(x=>({lat:round(x.lat,6),lon:round(x.lon,6)})),areaHa:round(polygonAreaHa(fieldPoints),4),perimeterKm:round(perimeterKm(fieldPoints),4),pin:p,createdAt:new Date().toISOString()};fields.unshift(entry);if($('es-compare-area-ha'))$('es-compare-area-ha').value=entry.areaHa>0?entry.areaHa:1;if($('es-water-area'))$('es-water-area').value=entry.areaHa>0?entry.areaHa:1;if($('es-fert-area'))$('es-fert-area').value=entry.areaHa>0?entry.areaHa:1;if($('es-calendar-area'))$('es-calendar-area').value=entry.areaHa>0?entry.areaHa:1;if(!writeStore('earthscope-fields-v3',fields)){alert('Browser storage is full; export or remove old records.');return}collection.unshift(entry);writeStore('earthscope-collections-v3',collection);renderFields();renderCollections();$('es-field-status').textContent=`Saved ${entry.name}: ${entry.areaHa} ha (${round(entry.areaHa*2.47105,3)} acres).`});$('es-export-field').addEventListener('click',()=>{if(fieldPoints.length<3){alert('Draw a boundary first.');return}const ring=fieldPoints.map(p=>[p.lon,p.lat]);ring.push(ring[0]);download('earthscope-field.geojson',JSON.stringify({type:'FeatureCollection',features:[{type:'Feature',properties:{name:$('es-field-name').value||'Field',area_ha:round(polygonAreaHa(fieldPoints),4),perimeter_km:round(perimeterKm(fieldPoints),4)},geometry:{type:'Polygon',coordinates:[ring]}}]},null,2),'application/geo+json')});$('es-print-fields').addEventListener('click',()=>{if(fieldPoints.length<3){alert('Draw a boundary first.');return}const w=window.open('','_blank');if(!w){window.print();return}w.document.write(`<html><head><title>EARTHSCOPE Field Worksheet</title><style>body{font:12pt Arial;margin:18mm;color:#111}h1{font-size:20pt}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:7px;text-align:left}@page{size:A4;margin:15mm}</style></head><body><h1>EARTHSCOPE Field Boundary Worksheet</h1><p>Generated ${new Date().toLocaleString()}</p><p>Field: ${esc($('es-field-name').value||'Unnamed field')}</p><p>Area: ${fmt(polygonAreaHa(fieldPoints))} ha / ${fmt(polygonAreaHa(fieldPoints)*2.47105)} acres</p><p>Perimeter: ${fmt(perimeterKm(fieldPoints))} km</p><p>Vertices: ${fieldPoints.length}</p><p>Notes: ${esc($('es-field-notes').value)}</p><p>Coordinate and area estimates are not a legal cadastral survey.</p><table><tr><th>Vertex</th><th>Latitude</th><th>Longitude</th></tr>${fieldPoints.map((p,i)=>`<tr><td>${i+1}</td><td>${p.lat.toFixed(6)}</td><td>${p.lon.toFixed(6)}</td></tr>`).join('')}</table><script>window.print()<\/script></body></html>`);w.document.close()});
 function renderFields(){const box=$('es-fields-list');if(!box)return;if(!fields.length){box.innerHTML='<p class="es-muted">No saved field boundaries yet.</p>';return}box.innerHTML=fields.map(f=>`<article class="es-list-item"><div><b>${esc(f.name)}</b><small>${fmt(f.areaHa)} ha · ${fmt(f.perimeterKm)} km perimeter · ${new Date(f.createdAt).toLocaleDateString()}${f.notes?' · '+esc(f.notes):''}</small></div><div><button class="es-secondary" data-field-open="${esc(f.id)}">Show</button><button class="es-secondary" data-field-delete="${esc(f.id)}">Delete</button></div></article>`).join('');box.querySelectorAll('[data-field-open]').forEach(b=>b.addEventListener('click',()=>{const f=fields.find(x=>x.id===b.dataset.fieldOpen);if(f){fieldPoints=f.coordinates;if($('es-compare-area-ha'))$('es-compare-area-ha').value=f.areaHa>0?f.areaHa:1;if($('es-water-area'))$('es-water-area').value=f.areaHa>0?f.areaHa:1;if($('es-fert-area'))$('es-fert-area').value=f.areaHa>0?f.areaHa:1;if($('es-calendar-area'))$('es-calendar-area').value=f.areaHa>0?f.areaHa:1;window.EARTHSCOPE_BRIDGE?.drawField(fieldPoints);renderFieldStatus(true);close();goMain('explore')}}));box.querySelectorAll('[data-field-delete]').forEach(b=>b.addEventListener('click',()=>{fields=fields.filter(x=>x.id!==b.dataset.fieldDelete);collection=collection.filter(x=>x.id!==b.dataset.fieldDelete);writeStore('earthscope-fields-v3',fields);writeStore('earthscope-collections-v3',collection);renderFields();renderCollections()}))}
 function cropScenario(prefix){const v=id=>Number($(prefix+id).value)||0;const name=$(prefix+'-name').value.trim()||'Crop';const yieldKg=v('-yield'),price=v('-price'),cost=v('-cost'),area=Math.max(0,Number($('es-compare-area-ha')?.value)||1),loss=Math.min(100,Math.max(0,v('-loss')))/100,qty=yieldKg*area*(1-loss),revenue=qty*price,profit=revenue-cost,be=qty?cost/qty:NaN;return{name,yieldKg,area,price,cost,loss:loss*100,qty,revenue,profit,breakEven:be,low:revenue*.8-cost,high:revenue*1.2-cost}}
 function calcCompare(){cropRows=['es-ca','es-cb','es-cc'].map(cropScenario).sort((a,b)=>b.profit-a.profit);const out=$('es-crop-compare-results');if(!out)return;out.innerHTML=`<div class="es-table-wrap"><table class="es-table"><thead><tr><th>Rank*</th><th>Crop</th><th>Saleable yield</th><th>Revenue</th><th>Costs</th><th>Net scenario</th><th>Break-even / kg</th><th>Net if revenue −20%</th></tr></thead><tbody>${cropRows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${fmt(r.qty)} kg</td><td>${fmt(r.revenue)}</td><td>${fmt(r.cost)}</td><td class="${r.profit<0?'es-negative':'es-positive'}">${fmt(r.profit)}</td><td>${Number.isFinite(r.breakEven)?fmt(r.breakEven):'—'}</td><td>${fmt(r.low)}</td></tr>`).join('')}</tbody></table></div><p class="es-muted">*Ranked by entered profit scenario only. Currency is whatever currency the entered prices/costs use; no independent market data is implied. Yield is entered per hectare and multiplied by the shared ${fmt(Number($('es-compare-area-ha')?.value)||1)} ha area; costs are total costs for that selected area. All crops are assumed to share the same duration.</p>`;return cropRows}
 $('es-calc-compare').addEventListener('click',calcCompare);$('es-save-crop-plan').addEventListener('click',()=>{const rows=calcCompare(),area=Math.max(0,Number($('es-compare-area-ha').value)||1);if(!rows.length){alert('Calculate a crop comparison first.');return}const item={id:Date.now().toString(36),type:'crop',name:`Crop comparison · ${fmt(area)} ha`,areaHa:area,scenarios:rows.map(x=>({...x})),notes:`${rows.map(x=>`${x.name}: net ${fmt(x.profit)}`).join(' · ')} · scenario only`,createdAt:new Date().toISOString()};collection.unshift(item);if(!writeStore('earthscope-collections-v3',collection)){alert('Browser storage is full; export or remove old collection records.');return}renderCollections();alert('Crop scenarios saved. Results are your entered assumptions, not yield/profit forecasts.')});$('es-export-compare').addEventListener('click',()=>{const rows=calcCompare(),csv=[['rank','crop','yield_kg_ha','saleable_kg','price_per_kg','revenue','costs','profit_scenario','break_even_price','net_revenue_minus_20pct','net_revenue_plus_20pct'].join(','),...rows.map((r,i)=>[i+1,r.name,r.yieldKg,r.qty,r.price,r.revenue,r.cost,r.profit,r.breakEven,r.low,r.high].map(csvCell).join(','))].join('\n');download('earthscope-crop-comparison.csv',csv,'text/csv')});$('es-print-compare').addEventListener('click',()=>{calcCompare();window.print()});function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}
 $('es-load-soil').addEventListener('click',async()=>{const p=pinCoords(),out=$('es-soil-output');if(!p){out.textContent='Select a map pin first.';return}out.textContent='Requesting SoilGrids…';try{const r=await api('soil',{lat:p.lat,lon:p.lon});out.textContent=JSON.stringify(r.data?.properties||r.data,null,2)+'\n\nSoilGrids is a gridded model and may not represent this parcel. Collect a soil sample for crop/fertilizer decisions.'}catch(e){out.textContent='Soil context unavailable: '+e.message}});
