 function buildCalendar(){const crop=$('es-calendar-crop').value.trim()||'Crop',date=$('es-calendar-date').value,days=Number($('es-calendar-maturity').value),area=Number($('es-calendar-area').value),out=$('es-calendar-result');if(!date||!(days>0&&days<=1500&&area>0)){out.textContent='Enter a valid date, maturity duration and area.';return null}const start=new Date(date+'T12:00:00Z');const add=n=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+Math.round(n));return d.toISOString().slice(0,10)};const rows=[['Planning start / planting',date,'Use the locally confirmed sowing/transplanting date.'],['Early establishment',add(days*.1),'Generic milestone at 10% of user-supplied duration.'],['Vegetative / canopy phase',add(days*.3),'Generic milestone at 30%; crop-specific stages vary.'],['Reproductive / fruiting phase',add(days*.6),'Generic milestone at 60%; crop-specific stages vary.'],['Expected first harvest',add(days),'User-entered maturity estimate; not a forecast.'],['Follow-up / final harvest',add(days*1.25),'Illustrative only; replace with variety-specific harvest interval.']];out.innerHTML=`<p><b>${esc(crop)}</b> · ${fmt(area)} ha · user-supplied first-harvest duration ${days} days</p><div class="es-table-wrap"><table class="es-table"><thead><tr><th>Milestone</th><th>Planning date</th><th>Notes</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join('')}</tbody></table></div><p class="es-muted">Generic schedule only; not a local planting calendar. Verify variety, nursery/transplant time, climate, day length, pest pressure, local extension guidance, and market window.</p>`;return {crop,date,days,area,rows}}
 $('es-build-calendar').addEventListener('click',buildCalendar);$('es-print-calendar').addEventListener('click',()=>{if(!buildCalendar())return;window.print()});
 $('es-load-market').addEventListener('click',async()=>{const commodity=$('es-market-commodity').value.trim(),state=$('es-market-state').value.trim(),district=$('es-market-district').value.trim(),out=$('es-market-result');if(!commodity){out.textContent='Enter a commodity name.';return}out.textContent='Requesting daily mandi data…';try{const r=await api('market-prices',{commodity,state,district}),d=r.data||{},rows=d.records||d.data||d.results||[];if(!Array.isArray(rows)||!rows.length){out.textContent=JSON.stringify(d,null,2)+'\n\nProvider returned no recognizable records. See source URL in response or re-check filters.';return}out.innerHTML=`<p>${esc(r.note||'Reported market records. Check dates and units.')}</p><div class="es-table-wrap"><table class="es-table"><thead><tr><th>Date</th><th>Market</th><th>Variety / grade</th><th>Min</th><th>Modal</th><th>Max</th><th>Unit</th></tr></thead><tbody>${rows.slice(0,50).map(x=>`<tr><td>${esc(x.arrival_date||x.date||'—')}</td><td>${esc(x.market||x.market_name||'—')}</td><td>${esc(x.variety||x.grade||'—')}</td><td>${esc(x.min_price||'—')}</td><td>${esc(x.modal_price||x.modalprice||'—')}</td><td>${esc(x.max_price||'—')}</td><td>${esc(x.commodity_unit||x.unit||'check source')}</td></tr>`).join('')}</tbody></table></div><p class="es-muted">Source: Government of India data.gov.in / AGMARKNET. Wholesale records may be stale or in a unit different from your sales contract; confirm current price at market.</p>`}catch(e){out.textContent='Mandi lookup unavailable: '+e.message+'\nConfigure data_gov_in_api_key server-side; this is an API integration, not a generated price.'}});
