 $('es-compare-land').addEventListener('click',async()=>{const a=pinCoords(),lat=Number($('es-land-b-lat').value),lon=Number($('es-land-b-lon').value),bname=$('es-land-b-name').value.trim()||'Candidate B',out=$('es-land-result');if(!a){out.textContent='Select location A on the main map first.';return}if(!Number.isFinite(lat)||lat< -90||lat>90||!Number.isFinite(lon)||lon< -180||lon>180){out.textContent='Enter valid candidate B coordinates.';return}out.textContent='Loading forecast, soil model and air-quality model for both points…';async function one(p){const settled=await Promise.allSettled([api('weather',{lat:p.lat,lon:p.lon}),api('soil',{lat:p.lat,lon:p.lon}),api('air-quality',{lat:p.lat,lon:p.lon})]);return {p,weather:settled[0].status==='fulfilled'?settled[0].value:null,soil:settled[1].status==='fulfilled'?settled[1].value:null,air:settled[2].status==='fulfilled'?settled[2].value:null,errors:settled.map((x,i)=>x.status==='rejected'?['weather','soil','air quality'][i]+': '+x.reason.message:null).filter(Boolean)}}try{const [aa,bb]=await Promise.all([one(a),one({name:bname,lat,lon})]);const summary=x=>{const d=x.weather?.data||{},c=d.current||{},aq=x.air?.data?.current||{},sp=x.soil?.data||{};return `<h4>${esc(x.p.name)}</h4><p>${x.p.lat.toFixed(4)}, ${x.p.lon.toFixed(4)}</p><ul class="es-list"><li>Current modeled temperature: ${c.temperature_2m!==undefined?esc(c.temperature_2m+' '+(d.current_units?.temperature_2m||'°C')):'unavailable'}</li><li>Relative humidity: ${c.relative_humidity_2m!==undefined?esc(c.relative_humidity_2m+'%'):'unavailable'}</li><li>Wind: ${c.wind_speed_10m!==undefined?esc(c.wind_speed_10m+' '+(d.current_units?.wind_speed_10m||'km/h')):'unavailable'}</li><li>US AQI model: ${aq.us_aqi??'unavailable'}; PM2.5: ${aq.pm2_5??'unavailable'}</li><li>Soil profile: ${x.soil?'gridded context returned':'unavailable'}</li></ul>${x.errors.length?`<p class="es-muted">Unavailable: ${esc(x.errors.join('; '))}</p>`:''}`} ;out.innerHTML=`<div class="es-grid"> <article class="es-card">${summary(aa)}</article><article class="es-card">${summary(bb)}</article></div><p class="es-muted">Comparison is location-level screening, not land due diligence. Confirm title, survey, legal access, water rights, groundwater reliability, contamination, flood risk, farm road access, measured soil, and local costs independently. Model values are not plot measurements.</p>`}catch(e){out.textContent='Could not compare locations: '+e.message}});
