 $('es-print-farm-report').addEventListener('click',()=>{const p=pinCoords();if(!p){alert('Select a location pin first.');return}const crops=calcCompare()||[];const d=fields[0]||null;const water=$('es-water-result').textContent||'Not calculated';const market=$('es-market-result').innerText||'Not retrieved';const w=window.open('','_blank');if(!w){window.print();return}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>EARTHSCOPE A4 Location & Farm Report</title><style>body{font:11pt/1.45 Arial,sans-serif;color:#111;margin:0}main{padding:15mm}h1{font-size:22pt;margin-bottom:4px}h2{font-size:14pt;border-bottom:1px solid #888;padding-bottom:4px;margin-top:18px}small,.muted{color:#444}.box{border:1px solid #999;padding:9px;margin:8px 0}.mapshot{max-width:100%;max-height:60mm;border:1px solid #999;margin:5px 0}table{border-collapse:collapse;width:100%;font-size:9pt}th,td{border:1px solid #aaa;padding:6px;text-align:left}th{background:#eee}@page{size:A4;margin:0} .break{break-inside:avoid} </style></head><body><main><h1>EARTHSCOPE · Field Intelligence Report</h1><p>Generated ${esc(new Date().toLocaleString())} · Report based on selected point and user-entered assumptions</p><div class="box"><b>Selected location</b><br>${esc(p.name)}<br>Latitude ${p.lat.toFixed(6)} · Longitude ${p.lon.toFixed(6)}<br><a href="https://www.openstreetmap.org/?mlat=${p.lat}&mlon=${p.lon}#map=14/${p.lat}/${p.lon}">Open mapped location</a></div><h2>Field boundary</h2><div id="mapImage"></div><p class="muted">Map preview is included when the browser allows a safe canvas export; otherwise use the coordinate link above.</p>${d?`<p>${esc(d.name)} · ${fmt(d.areaHa)} ha / ${fmt(d.areaHa*2.47105)} acres · perimeter ${fmt(d.perimeterKm)} km.</p>`:'No saved field boundary was attached. Draw a boundary to add area details.'}<p>${fieldPoints.length>=3?'Current boundary area: '+fmt(polygonAreaHa(fieldPoints))+' ha; perimeter '+fmt(perimeterKm(fieldPoints))+' km.':'No unsaved current polygon.'}</p><h2>Crop scenario comparison</h2><table><thead><tr><th>Crop</th><th>Saleable kg</th><th>Revenue</th><th>Costs</th><th>Net scenario</th><th>Break-even/kg</th></tr></thead><tbody>${crops.map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.qty)}</td><td>${fmt(x.revenue)}</td><td>${fmt(x.cost)}</td><td>${fmt(x.profit)}</td><td>${Number.isFinite(x.breakEven)?fmt(x.breakEven):'—'}</td></tr>`).join('')}</tbody></table><h2>Water planning result</h2><p>${esc(water)}</p><h2>Mandi lookup status</h2><p>${esc(market.slice(0,1000))}</p><h2>Risk & uncertainty notes</h2><p>Check gridded soil and weather context against local measurements. Crop profitability depends on actual farm-gate price, grade, yield, labor, water, transport, losses and market access. This report is not a land survey, agronomic prescription, disaster warning or guarantee of future income.</p><small>EARTHSCOPE · Data source values only appear when a provider response has been loaded; user assumptions are labeled. Verify with local extension and market authorities.</small></main><script>window.onload=()=>{try{const canvas=window.opener?.document?.querySelector('#map canvas');if(canvas){const img=document.createElement('img');img.className='mapshot';img.src=canvas.toDataURL('image/png');document.getElementById('mapImage').appendChild(img)}}catch{}setTimeout(()=>window.print(),500)};<\/script></body></html>`);w.document.close();$('es-report-status').textContent='Opened a print-ready report in a separate window. Choose Save as PDF in the print dialog; check pop-up permission if nothing opened.'});
